import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getAnnouncementHandler } from "../handlers/getAnnouncementHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof getAnnouncementHandler>>;

export function useGetAnnouncement(
  teamPk: TeamPartition,
  announcementId: string,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getAnnouncement", teamPk, announcementId],
    queryFn: () => getAnnouncementHandler(teamPk, announcementId),
    ...options,
  });
}
